/**
 * CAMERA RECOGNITION - VERSION ULTRA-ROBUSTE
 * Correction spécifique : Écran noir sur PC (Chrome/Edge/Firefox)
 */
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

// --- STYLES CONSTANTS ---
const COLORS = {
    primary: '#4F46E5',
    danger: '#EF4444',
    success: '#10B981',
    bg: '#F8FAFC',
    card: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
    // REFS
    const videoRef = useRef(null);
    const streamRef = useRef(null);
    const canvasRef = useRef(null);

    // STATES
    const [isActive, setIsActive] = useState(false);
    const [isDetecting, setIsDetecting] = useState(false);
    const [progress, setProgress] = useState(0);
    const [error, setError] = useState(null);
    const [result, setResult] = useState(null);

    /**
     * ✅ FONCTION DE DÉMARRAGE "FORCE PLAY"
     */
    const startCamera = async () => {
        setError(null);
        try {
            // 1. Demande du flux avec des paramètres standards PC
            const constraints = {
                video: {
                    width: { ideal: 1280 },
                    height: { ideal: 720 },
                    frameRate: { ideal: 30 }
                },
                audio: false
            };

            const stream = await navigator.mediaDevices.getUserMedia(constraints);
            streamRef.current = stream;

            if (videoRef.current) {
                // 2. Attribution du flux
                videoRef.current.srcObject = stream;

                // 3. FORCE LES ATTRIBUTS (Crucial pour éviter l'écran noir)
                videoRef.current.setAttribute('autoplay', '');
                videoRef.current.setAttribute('muted', '');
                videoRef.current.setAttribute('playsinline', '');
                videoRef.current.muted = true;

                // 4. DÉMARRAGE FORCÉ
                // On tente de jouer la vidéo immédiatement
                try {
                    await videoRef.current.play();
                    setIsActive(true);
                    console.log("Flux vidéo démarré");
                } catch (playErr) {
                    console.error("Le play() a échoué, tentative de retry...", playErr);
                    // Certains navigateurs demandent un délai
                    setTimeout(() => videoRef.current.play(), 500);
                }
            }
        } catch (err) {
            console.error("Erreur Camera:", err);
            setError(`Accès refusé ou caméra occupée (${err.name})`);
        }
    };

    const stopCamera = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
        setIsActive(false);
        setIsDetecting(false);
    };

    /**
     * ✅ CYCLE DE RECONNAISSANCE (10 SECONDES)
     */
    const runDetection = async () => {
        if (!isActive || isDetecting) return;

        setIsDetecting(true);
        setProgress(0);
        setResult(null);

        const startTime = Date.now();
        const duration = 10000;
        let bestMatch = null;

        const interval = setInterval(async () => {
            const elapsed = Date.now() - startTime;
            setProgress(Math.min(100, (elapsed / duration) * 100));

            // Capture frame
            if (videoRef.current && canvasRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                canvas.getContext('2d').drawImage(video, 0, 0);
                const base64 = canvas.toDataURL('image/jpeg', 0.8);

                try {
                    const res = await attendanceAPI.recognize(base64);
                    if (res?.data?.success && (!bestMatch || res.data.confidence > bestMatch.confidence)) {
                        bestMatch = { ...res.data, photo: base64 };
                    }
                } catch (e) { /* ignore error in loop */ }
            }

            if (elapsed >= duration) {
                clearInterval(interval);
                setIsDetecting(false);
                if (bestMatch) {
                    setResult(bestMatch);
                    addNotification?.(`Identifié : ${bestMatch.student}`, 'success');
                } else {
                    setError("Aucun visage reconnu après 10s.");
                }
            }
        }, 800);
    };

    // Nettoyage au démontage
    useEffect(() => () => stopCamera(), []);

    return (
        <div style={styles.container}>
            <div style={styles.card}>
                <h2 style={styles.title}>Scanner de Présence PC</h2>

                <div style={styles.videoContainer}>
                    <video
                        ref={videoRef}
                        autoPlay
                        muted
                        playsInline
                        style={{
                            ...styles.video,
                            border: isDetecting ? `4px solid ${COLORS.primary}` : '4px solid transparent'
                        }}
                    />

                    {!isActive && (
                        <div style={styles.overlay}>
                            <button onClick={startCamera} style={styles.btnStart}>
                                ALLUMER LA CAMÉRA
                            </button>
                        </div>
                    )}

                    {isDetecting && <div style={styles.scanLine} />}
                </div>

                <div style={styles.progressTrack}>
                    <div style={{ ...styles.progressFill, width: `${progress}%` }} />
                </div>

                <div style={styles.controls}>
                    <button 
                        onClick={runDetection} 
                        disabled={!isActive || isDetecting}
                        style={(!isActive || isDetecting) ? styles.btnDisabled : styles.btnAction}
                    >
                        {isDetecting ? 'ANALYSE...' : 'LANCER LE SCAN'}
                    </button>

                    {isActive && (
                        <button onClick={stopCamera} style={styles.btnStop}>ÉTEINDRE</button>
                    )}
                </div>

                {error && <p style={styles.error}>{error}</p>}

                {result && (
                    <div style={styles.resultBox}>
                        <img src={result.photo} style={styles.thumb} alt="Captured" />
                        <div>
                            <p><strong>Étudiant :</strong> {result.student}</p>
                            <p><strong>Confiance :</strong> {(result.confidence * 100).toFixed(1)}%</p>
                        </div>
                    </div>
                )}
            </div>

            <canvas ref={canvasRef} style={{ display: 'none' }} />
        </div>
    );
};

// --- STYLES ---
const styles = {
    container: { minHeight: '100vh', backgroundColor: COLORS.bg, padding: '40px', display: 'flex', justifyContent: 'center' },
    card: { backgroundColor: COLORS.card, padding: '30px', borderRadius: '20px', boxShadow: '0 10px 30px rgba(0,0,0,0.1)', width: '100%', maxWidth: '800px' },
    title: { textAlign: 'center', marginBottom: '20px', color: '#1E293B' },
    videoContainer: { position: 'relative', width: '100%', aspectRatio: '16/9', backgroundColor: '#000', borderRadius: '15px', overflow: 'hidden' },
    video: { width: '100%', height: '100%', objectFit: 'cover' },
    overlay: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(0,0,0,0.6)' },
    scanLine: { position: 'absolute', top: 0, left: 0, width: '100%', height: '4px', background: COLORS.primary, boxShadow: '0 0 15px blue', animation: 'moveScan 2s infinite linear' },
    btnStart: { padding: '15px 30px', fontSize: '16px', fontWeight: 'bold', cursor: 'pointer', backgroundColor: COLORS.primary, color: 'white', border: 'none', borderRadius: '10px' },
    progressTrack: { width: '100%', height: '10px', backgroundColor: '#E2E8F0', borderRadius: '5px', marginTop: '20px', overflow: 'hidden' },
    progressFill: { height: '100%', backgroundColor: COLORS.primary, transition: 'width 0.1s linear' },
    controls: { display: 'flex', gap: '15px', marginTop: '20px' },
    btnAction: { flex: 2, padding: '15px', backgroundColor: COLORS.primary, color: 'white', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' },
    btnDisabled: { flex: 2, padding: '15px', backgroundColor: '#CBD5E1', color: 'white', border: 'none', borderRadius: '10px', cursor: 'not-allowed' },
    btnStop: { flex: 1, padding: '15px', backgroundColor: 'transparent', border: `2px solid ${COLORS.danger}`, color: COLORS.danger, borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' },
    error: { color: COLORS.danger, marginTop: '15px', textAlign: 'center', fontWeight: 'bold' },
    resultBox: { marginTop: '20px', padding: '15px', border: '1px solid #E2E8F0', borderRadius: '10px', display: 'flex', gap: '20px', alignItems: 'center' },
    thumb: { width: '80px', height: '80px', borderRadius: '8px', objectFit: 'cover' },
    // Animation CSS
    '@keyframes moveScan': { '0%': { top: '0%' }, '100%': { top: '100%' } }
};

export default CameraRecognition;
